  "properties": {
    "data": {
      "description": "Base64-encoded audio data.",
      "type": "string"
    },
    "format": {
      "description": "The audio format (e.g., \"wav\", \"mp3\").",
      "type": "string"
    }
  }
}

{
  "title": "functions.expression.StringInputSchema",
  "description": "Schema for a string input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the string.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "enum": {
      "description": "If provided, the string must be one of these values.",
      "anyOf": [
        {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "type": {
      "$ref": "functions.expression.StringInputSchemaType"
    }
  }
}

{
  "title": "functions.expression.ObjectInputSchema",
  "description": "Schema for an object input with named properties.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the object.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "properties": {
      "additionalProperties": {
        "$ref": "functions.expression.InputSchema"
      },
      "description": "Schema for each property in the object.",
      "type": "object"
    },
    "required": {
      "description": "List of property names that must be present.",
      "anyOf": [
        {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "type": {
      "$ref": "functions.expression.ObjectInputSchemaType"
    }
  }
}
